<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { Lock, User, OfficeBuilding, ArrowRight, Connection, CircleCheck } from '@element-plus/icons-vue'
import { api } from '../api'
import { useApp } from '../store'
import TrialBanner from './TrialBanner.vue'
import BrandMark from './BrandMark.vue'
const app = useApp(), router = useRouter(), route = useRoute(), busy = ref(false)
const form = reactive({ username: 'admin', password: '', confirm: '', company_name: '' })
const valid = computed(() => form.username.length >= 3 && form.password.length > 0 && (!app.needsSetup || form.password.length >= 8 && form.company_name.trim() && form.password === form.confirm))
async function login() { if (!valid.value || busy.value) return; busy.value = true; try { if (app.needsSetup) { await api('/setup', 'POST', form); app.needsSetup = false } await api('/auth/login', 'POST', form); await app.refreshMe(); if (!(route.path === '/system' && route.query.tab === 'license')) await router.push('/') } catch {} finally { busy.value = false } }
</script>
<template>
  <div class="login-root"><TrialBanner/><div class="login-screen">
    <section class="login-story"><div class="brand large"><BrandMark/><div :title="app.branding.app_name">{{ app.branding.brand_short }}<small>进销存与往来管理</small></div></div><div class="story-body"><div class="eyebrow">CONNECTED BUSINESS, CLEARER DECISIONS</div><h1>把业务连起来，<br>让经营看得清。</h1><p>从每一次采购，到每一笔回款。<br>让商品、库存与往来账务，形成完整的业务闭环。</p><div class="story-features"><span><el-icon><Connection /></el-icon>进销存一体化</span><span><el-icon><CircleCheck /></el-icon>每笔业务可追溯</span><span><el-icon><Lock /></el-icon>数据本地保存</span></div><div class="story-art"><i></i><i></i><i></i><div class="art-card"><span>BUSINESS IN SYNC</span><b>采购 → 库存 → 销售</b><small>应付 · 付款 &nbsp; / &nbsp; 应收 · 回款</small></div></div></div><footer>{{ app.branding.app_name }} <span>V1.1</span></footer></section>
    <section class="login-form-side"><div class="login-card"><div class="login-badge">{{ app.needsSetup ? '开启 10 天完整试用' : app.company }}</div><h2>{{ app.needsSetup ? '欢迎使用' + app.branding.brand_short : '欢迎回来' }}</h2><p class="muted">{{ app.needsSetup ? '设置企业信息与管理员账号，开始管理您的业务。' : '登录账号，查看今天的经营动态。' }}</p><el-form label-position="top" @submit.prevent="login" class="login-form"><el-form-item v-if="app.needsSetup" label="企业名称"><el-input v-model="form.company_name" :prefix-icon="OfficeBuilding" placeholder="请输入企业名称" size="large" maxlength="80" /></el-form-item><el-form-item label="用户名"><el-input v-model="form.username" :prefix-icon="User" placeholder="请输入用户名" size="large" autocomplete="username" maxlength="64" /></el-form-item><el-form-item label="密码"><el-input v-model="form.password" :prefix-icon="Lock" :placeholder="app.needsSetup ? '至少 8 位，包含数字和非数字字符' : '请输入密码'" type="password" show-password size="large" :autocomplete="app.needsSetup ? 'new-password' : 'current-password'" /></el-form-item><el-form-item v-if="app.needsSetup" label="确认密码"><el-input v-model="form.confirm" :prefix-icon="Lock" placeholder="再次输入密码" type="password" show-password size="large" autocomplete="new-password" /></el-form-item><el-button class="login-submit" type="primary" size="large" :loading="busy" :disabled="!valid" native-type="submit">{{ app.needsSetup ? '初始化并进入系统' : '登录系统' }}<el-icon><ArrowRight /></el-icon></el-button></el-form><p v-if="!app.needsSetup" class="default-account">首次登录：用户名 <b>admin</b> / 密码 <b>admin</b><br><small>登录后可在右上角账号菜单中修改密码</small></p><p class="login-note"><el-icon><Lock /></el-icon>离线可用 · 数据保存在本机 · 不上传经营数据</p></div><div class="login-copyright">{{ app.branding.app_name }}</div></section>
  </div></div>
</template>
<style scoped>.login-root{min-height:100vh;display:flex;flex-direction:column}.login-root .login-screen{min-height:0;flex:1}.default-account{margin-top:19px;padding:12px 14px;border-radius:7px;background:#f1f6ff;color:#57749d;font-size:12px;line-height:1.9}.default-account small{font-size:11px;color:#8798af}@media(max-width:680px){.login-root .login-form-side{min-height:calc(100vh - 74px)}}</style>
